from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)
ws=wb['Task']
print('\nTask row 10 H:L year headers:')
for col in range(8,13):
    print(f'{get_column_letter(col)}10={ws.cell(10,col).value!r}')
print('\nTask column D series codes rows 12-17,19-24,26-31:')
for start,end in [(12,17),(19,24),(26,31)]:
    print(f'Rows {start}-{end}:')
    for r in range(start,end+1):
        vals={get_column_letter(c):ws.cell(r,c).value for c in range(1,8)}
        print(f' row {r}: D={ws.cell(r,4).value!r}; A-G={vals}')
print('\nTask department identifiers rows 35-40 (B:D and A-G):')
for r in range(35,41):
    vals={get_column_letter(c):ws.cell(r,c).value for c in range(1,8)}
    print(f' row {r}: B={ws.cell(r,2).value!r}, D={ws.cell(r,4).value!r}; A-G={vals}')
print('\nTask stat labels rows 42-47 A-G:')
for r in range(42,48):
    vals={get_column_letter(c):ws.cell(r,c).value for c in range(1,8)}
    print(f' row {r}: {vals}')
print('\nTask row 50 A-G:')
vals={get_column_letter(c):ws.cell(50,c).value for c in range(1,8)}
print(f' row 50: {vals}')

ds=wb['Data']
print('\nData first 10 columns rows 20-38:')
for r in range(20,39):
    vals=[ds.cell(r,c).value for c in range(1,11)]
    print(f' row {r}: {vals}')
