        print(f'row {r}:', vals)
print('\nColumns A:Z for rows 18-21:')
for r in range(18,22):
    vals=[]
    for c in range(1,27):
        v=ds.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}={v!r}')
    print('row', r, '; '.join(vals) if vals else '(all None)')
